(* [comment removed for export] *)
Definition FDW_OPEN_STACK : Z := 240 + 4096.

Section Asm.
Variable AI : AMallocIface.
Notation CI := (aci AI).
Variable fflag : alayout -> Z -> Z -> Z.
Variable rng_fs : alayout -> footprint -> Prop.
Hypothesis FFLAG : fake_flag_law AI fflag.
Hypothesis FREL : fake_release_law AI fflag.
Variable kk : nat.
Hypothesis SM0K : stack_malloc_0k_stmt AI fflag rng_fs kk.
Notation FB0 F := (mkABlock (ABFake 0) F 64).

(* [comment removed for export] *)
Definition fdw_frame (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock) (m m3 : amem)
    (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (SPV lo FF : Z) (junk : list byte) : Prop :=
  FF mod 64 = 0 /\ ablk FF (FF + 64) /\ FF + 64 <= ATOP /\ rng RNG FF 64 /\ rng RNG (shad FF) 8
  /\ (forall b, In b LB -> FF + 64 <= ab_addr b \/ ab_addr b + ab_size b <= FF)
  /\ AHEAP AI L RNG st (FB0 FF :: LB) m3
  /\ magree asegs (aclient_addr CI LB SPV) m m3 /\ mem_inv asegs m3
  /\ rw_cells asegs m3 (SPV + -104) (FRBf ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11)
  /\ rw_cells asegs m3 FF (FDHDR FF (fflag L 0 FF) (firstn 24 junk) (skipn 28 junk))
  /\ rw_cells asegs m3 (shad FF) FDSH
  /\ stk asegs m3 lo (SPAf SPV) /\ stk asegs m3 (SPAf SPV + 120) (SPV + -104).

(* [comment removed for export] *)
Lemma fdw_open : forall (L : alayout) (RNG : footprint)
    (ra gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (FR : bvmap 5 word) (fc : bv 32) (m : amem) (st : astate) (LB : list ablock)
    (SPV DST dcap S size maxLog W wks lo : Z) (Q : machine_state -> Prop),
  AHEAP AI L RNG st LB m -> fake0_lek kk LB ->
  (forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b)) ->
  stk asegs m lo SPV -> ATOP + 4096 <= lo -> lo <= SPV - FDW_OPEN_STACK ->
  SPV + 16 < al_top L -> SPV mod 16 = 0 ->
  mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
  rng RNG lo (al_top L - lo) -> rng_aimg RNG -> rng_fs L RNG ->
  0 <= wks < 2^64 ->
  (forall (FF : Z) (m3 : amem) (junk j8 j48 : list byte) (y5 y6 y7 y10 y11 y12 y13 y14 y16 y28 y29 y30 y31 : word),
     wks < 512 ->
     fdw_frame L RNG st LB m m3 ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 SPV lo FF junk ->
     rw_cells asegs m3 (SPAf SPV) [CB 40 j8; C8 (Z_to_bv 64 FF); CB 72 j48] ->
     evtF asegs RNG Q
       (MS (mkR (Z_to_bv 64 0x95dd8) (Z_to_bv 64 (SPAf SPV)) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAf SPV))
                y10 y11 y12 y13 y14 (Z_to_bv 64 (-1)) y16 (Z_to_bv 64 FF)
                (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) (Z_to_bv 64 dcap) (Z_to_bv 64 maxLog)
                (Z_to_bv 64 size) (Z_to_bv 64 S) (Z_to_bv 64 W) (Z_to_bv 64 wks) (Z_to_bv 64 DST) (Z_to_bv 64 2147450880)
                y28 y29 y30 y31)
           FR (Z_to_bv 64 0x960bc) fc None m3 (seg_rom asegs))) ->
  (forall (FF : Z) (m3 : amem) (junk j0' j32 j48 : list byte) (y5 y6 y7 y16 y28 y29 y30 y31 : word),
     512 <= wks ->
     fdw_frame L RNG st LB m m3 ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 SPV lo FF junk ->
     rw_cells asegs m3 (SPAf SPV) [CB 8 j0'; C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 2147450880); C8 (Z_to_bv 64 FF); CB 8 j32;
                                   C8 (Z_to_bv 64 FF); CB 72 j48] ->
     evtF asegs RNG Q
       (MS (mkR (Z_to_bv 64 0x95eb8) (Z_to_bv 64 (SPAf SPV)) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAf SPV))
                (Z_to_bv 64 W) (Z_to_bv 64 (FF + 48)) (Z_to_bv 64 (FF + 32)) (Z_to_bv 64 S) (Z_to_bv 64 size)
                (Z_to_bv 64 0) y16 (Z_to_bv 64 FF)
                (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) (Z_to_bv 64 dcap) (Z_to_bv 64 maxLog)
                (Z_to_bv 64 size) (Z_to_bv 64 S) (Z_to_bv 64 W) (Z_to_bv 64 wks) (Z_to_bv 64 (FF + 48)) (Z_to_bv 64 (FF + 32))
                y28 y29 y30 y31)
           FR (Z_to_bv 64 0x94978) fc None m3 (seg_rom asegs))) ->
  evtF asegs RNG Q
    (MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 S) (Z_to_bv 64 size)
             (Z_to_bv 64 maxLog) (Z_to_bv 64 W) (Z_to_bv 64 wks) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        FR (Z_to_bv 64 0x95d50) fc None m (seg_rom asegs)).
Proof.
