(* [comment removed for export] *)
Definition PAGf (LB : list ablock) (SPV DST dcap W wks : Z) (a : Z) : Prop :=
  aclient_addr CI LB SPV a /\ ~ (DST <= a < DST + dcap) /\ ~ (W <= a < W + wks).

(* [comment removed for export] *)
Definition dresA (DST dcap : Z) (R : res (list Z)) (m2 : amem) (rv : Z) : Prop :=
  match R with
  | Ok l => rv = zlen l /\ exists junk, u8arr asegs m2 DST (map (Z_to_bv 8) l ++ junk) /\ zlen junk = dcap - zlen l
  | Err e => rv = 2^64 - e /\ 0 < e < 120
  | Ub | NoFuel => False
  end.

(* [comment removed for export] *)
Lemma fdw_close : forall (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (m m4 : amem) (st : astate) (LB : list ablock) (SPV DST dcap W wks maxLog lo FF rv : Z) (src : list Z)
    (j0 : word) (csA : list cell)
    (x1 x5 x6 x7 x9 x10 x11 x12 x13 x14 x16 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word),
  AHEAP AI L RNG st (FB0 FF :: LB) m4 ->
  (forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b)) ->
  FF mod 64 = 0 -> ablk FF (FF + 64) -> FF + 64 <= ATOP -> rng RNG FF 64 -> rng RNG (shad FF) 8 ->
  (forall b, In b LB -> FF + 64 <= ab_addr b \/ ab_addr b + ab_size b <= FF) ->
  magree asegs (PAGf LB SPV DST dcap W wks) m m4 -> mem_inv asegs m4 ->
  rw_cells asegs m4 (Z.shiftr FF 3 + 2147450880) FDSH ->
  rw_cells asegs m4 FF [C8 j0] -> rw_cells asegs m4 (FF + 56) [C8 (Z_to_bv 64 (fflag L 0 FF))] ->
  rw_cells asegs m4 (SPV + -104) (FRBf ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11) ->
  rw_cells asegs m4 (SPAf SPV) csA -> cells_size csA = 120%nat ->
  stk asegs m4 lo (SPAf SPV) -> stk asegs m4 (SPAf SPV + 120) (SPV + -104) ->
  ATOP + 4096 <= lo -> lo <= SPV - FDW_OPEN_STACK -> SPV + 16 < al_top L -> SPV mod 16 = 0 -> rng RNG lo (al_top L - lo) ->
  (exists p A N, In (HB p A N) LB /\ A <= DST /\ DST + dcap <= A + N) -> 0 <= dcap ->
  dresA DST dcap (fse_decompress_wksp (repeat 0 256) dcap src maxLog wks) m4 rv -> 0 <= rv < 2^64 ->
  evtF asegs RNG (fse_decomp_postA AI L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV DST dcap W wks maxLog src lo m)
    (MS (mkR x1 (Z_to_bv 64 (SPAf SPV)) gp tp x5 x6 x7 (Z_to_bv 64 SPV) x9 x10 x11 x12 x13 x14 (Z_to_bv 64 rv) x16 (Z_to_bv 64 FF)
             (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        FR (Z_to_bv 64 0x960bc) fc None m4 (seg_rom asegs)).
Proof.
